CREATE TABLE suppliers (id VARCHAR(191) NOT NULL, organizationId VARCHAR(191) NOT NULL, code VARCHAR(191) NOT NULL, businessName VARCHAR(191) NOT NULL, tradeName VARCHAR(191) NULL, taxId VARCHAR(191) NULL, contactName VARCHAR(191) NULL, email VARCHAR(191) NULL, phone VARCHAR(191) NULL, address VARCHAR(191) NULL, paymentTerms VARCHAR(191) NULL, leadTimeDays INTEGER NOT NULL DEFAULT 0, notes TEXT NULL, isActive BOOLEAN NOT NULL DEFAULT true, createdAt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updatedAt DATETIME(3) NOT NULL, PRIMARY KEY (id), UNIQUE INDEX suppliers_organizationId_code_key(organizationId, code), INDEX suppliers_organizationId_businessName_idx(organizationId, businessName)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE supplier_products (id VARCHAR(191) NOT NULL, organizationId VARCHAR(191) NOT NULL, supplierId VARCHAR(191) NOT NULL, productId VARCHAR(191) NOT NULL, variantId VARCHAR(191) NULL, supplierSku VARCHAR(191) NULL, unitCost DECIMAL(12,2) NOT NULL DEFAULT 0, minimumOrder DECIMAL(12,3) NOT NULL DEFAULT 1, leadTimeDays INTEGER NULL, isPreferred BOOLEAN NOT NULL DEFAULT false, isActive BOOLEAN NOT NULL DEFAULT true, createdAt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updatedAt DATETIME(3) NOT NULL, PRIMARY KEY(id), UNIQUE INDEX supplier_products_supplierId_productId_variantId_key(supplierId, productId, variantId), INDEX supplier_products_organizationId_productId_variantId_idx(organizationId, productId, variantId), CONSTRAINT supplier_products_supplierId_fkey FOREIGN KEY(supplierId) REFERENCES suppliers(id) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE purchase_quotes (id VARCHAR(191) NOT NULL, organizationId VARCHAR(191) NOT NULL, supplierId VARCHAR(191) NOT NULL, folio VARCHAR(191) NOT NULL, status VARCHAR(191) NOT NULL DEFAULT 'draft', requestedAt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), validUntil DATETIME(3) NULL, notes TEXT NULL, createdBy VARCHAR(191) NULL, createdAt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updatedAt DATETIME(3) NOT NULL, PRIMARY KEY(id), UNIQUE INDEX purchase_quotes_organizationId_folio_key(organizationId, folio), INDEX purchase_quotes_organizationId_status_idx(organizationId, status), CONSTRAINT purchase_quotes_supplierId_fkey FOREIGN KEY(supplierId) REFERENCES suppliers(id) ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE purchase_quote_items (id VARCHAR(191) NOT NULL, quoteId VARCHAR(191) NOT NULL, productId VARCHAR(191) NOT NULL, variantId VARCHAR(191) NULL, description VARCHAR(191) NOT NULL, quantity DECIMAL(12,3) NOT NULL, unitCost DECIMAL(12,2) NOT NULL DEFAULT 0, taxRate DECIMAL(5,4) NOT NULL DEFAULT 0, PRIMARY KEY(id), INDEX purchase_quote_items_quoteId_idx(quoteId), CONSTRAINT purchase_quote_items_quoteId_fkey FOREIGN KEY(quoteId) REFERENCES purchase_quotes(id) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE purchase_orders (id VARCHAR(191) NOT NULL, organizationId VARCHAR(191) NOT NULL, supplierId VARCHAR(191) NOT NULL, quoteId VARCHAR(191) NULL, folio VARCHAR(191) NOT NULL, status VARCHAR(191) NOT NULL DEFAULT 'draft', locationType ENUM('location','cedis') NOT NULL, locationId VARCHAR(191) NOT NULL, expectedAt DATETIME(3) NULL, subtotal DECIMAL(12,2) NOT NULL DEFAULT 0, tax DECIMAL(12,2) NOT NULL DEFAULT 0, total DECIMAL(12,2) NOT NULL DEFAULT 0, notes TEXT NULL, createdBy VARCHAR(191) NULL, approvedBy VARCHAR(191) NULL, approvedAt DATETIME(3) NULL, sentAt DATETIME(3) NULL, completedAt DATETIME(3) NULL, cancelledAt DATETIME(3) NULL, createdAt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updatedAt DATETIME(3) NOT NULL, PRIMARY KEY(id), UNIQUE INDEX purchase_orders_organizationId_folio_key(organizationId, folio), INDEX purchase_orders_organizationId_status_idx(organizationId, status), CONSTRAINT purchase_orders_supplierId_fkey FOREIGN KEY(supplierId) REFERENCES suppliers(id) ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE purchase_order_items (id VARCHAR(191) NOT NULL, orderId VARCHAR(191) NOT NULL, productId VARCHAR(191) NOT NULL, variantId VARCHAR(191) NULL, description VARCHAR(191) NOT NULL, quantity DECIMAL(12,3) NOT NULL, receivedQuantity DECIMAL(12,3) NOT NULL DEFAULT 0, unitCost DECIMAL(12,2) NOT NULL, taxRate DECIMAL(5,4) NOT NULL DEFAULT 0, PRIMARY KEY(id), INDEX purchase_order_items_orderId_idx(orderId), CONSTRAINT purchase_order_items_orderId_fkey FOREIGN KEY(orderId) REFERENCES purchase_orders(id) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE goods_receipts (id VARCHAR(191) NOT NULL, organizationId VARCHAR(191) NOT NULL, orderId VARCHAR(191) NOT NULL, folio VARCHAR(191) NOT NULL, receivedBy VARCHAR(191) NULL, notes TEXT NULL, receivedAt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY(id), UNIQUE INDEX goods_receipts_organizationId_folio_key(organizationId, folio), INDEX goods_receipts_orderId_idx(orderId), CONSTRAINT goods_receipts_orderId_fkey FOREIGN KEY(orderId) REFERENCES purchase_orders(id) ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE goods_receipt_items (id VARCHAR(191) NOT NULL, receiptId VARCHAR(191) NOT NULL, orderItemId VARCHAR(191) NOT NULL, inventoryId VARCHAR(191) NOT NULL, quantity DECIMAL(12,3) NOT NULL, unitCost DECIMAL(12,2) NOT NULL, PRIMARY KEY(id), INDEX goods_receipt_items_receiptId_idx(receiptId), CONSTRAINT goods_receipt_items_receiptId_fkey FOREIGN KEY(receiptId) REFERENCES goods_receipts(id) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT goods_receipt_items_orderItemId_fkey FOREIGN KEY(orderItemId) REFERENCES purchase_order_items(id) ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
